package com.example.leetcodetrainer.curriculum.domain;
import com.example.leetcodetrainer.attempt.domain.StageType; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="skill_definition") public class SkillDefinition { @Id private UUID id; @Column(nullable=false,unique=true) private String code; @Column(nullable=false) private String displayName; @Enumerated(EnumType.STRING) private StageType legacyStageType; private boolean active; private int displayOrder; private Instant createdAt,updatedAt; protected SkillDefinition(){} public UUID getId(){return id;} public String getCode(){return code;} public String getDisplayName(){return displayName;} public StageType getLegacyStageType(){return legacyStageType;} public boolean isActive(){return active;} public int getDisplayOrder(){return displayOrder;} }
